from collections import deque
import sys


def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    M = int(input_data[1])
    grid = [list(row) for row in input_data[2 : 2 + N]]

    queue = deque()

    # Encontra a posição inicial do vazamento na primeira linha
    for j in range(M):
        if grid[0][j] == "o":
            queue.append((0, j))
            break

    # Simulação do escoamento via BFS
    while queue:
        r, c = queue.popleft()

        if r + 1 < N:
            if grid[r + 1][c] == ".":
                grid[r + 1][c] = "o"
                queue.append((r + 1, c))
            elif grid[r + 1][c] == "#":
                # Escorre para a esquerda sobre a prateleira
                if c - 1 >= 0 and grid[r][c - 1] == ".":
                    grid[r][c - 1] = "o"
                    queue.append((r, c - 1))
                # Escorre para a direita sobre a prateleira
                if c + 1 < M and grid[r][c + 1] == ".":
                    grid[r][c + 1] = "o"
                    queue.append((r, c + 1))

    # Impressão do resultado
    sys.stdout.write("\n".join("".join(row) for row in grid) + "\n")


if __name__ == "__main__":
    solve()
